{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plans & Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--accent:#7c5cff;--muted:#6b6b6b;--glass:rgba(255,255,255,0.6);--radius:14px}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.4;color:#222;background:var(--bg);-webkit-font-smoothing:antialiased}
    header{position:sticky;top:0;backdrop-filter:blur(6px);background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.35));border-bottom:1px solid rgba(10,10,10,0.03);display:flex;align-items:center;justify-content:space-between;padding:14px 20px;z-index:40}
    .brand{display:flex;gap:10px;align-items:center}
    .logo{width:44px;height:44px;border-radius:9px;background:linear-gradient(135deg,var(--accent),#4bc0c8);display:grid;place-items:center;color:white;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    .cta{background:var(--accent);color:white;padding:8px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    main{max-width:980px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;align-items:center}
    .panel{background:var(--card);padding:22px;border-radius:var(--radius);box-shadow:0 6px 22px rgba(20,20,60,0.06)}
    h1{margin:0;font-size:28px}
    p.lead{margin:8px 0;color:var(--muted)}

    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .plan{padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));border:1px solid rgba(10,10,10,0.04)}
    .plan h3{margin:0 0 8px 0}
    .price{font-size:22px;font-weight:800;color:var(--accent)}
    ul{padding-left:18px;margin:12px 0;color:var(--muted)}
    .muted{color:var(--muted);font-size:13px}
    .enroll{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:9px;background:#faf5ff;border:1px solid rgba(124,92,255,0.12);color:var(--accent);font-weight:700;text-decoration:none}

    .details{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:22px}
    .faq{padding:16px}
    .faq h4{margin:12px 0 6px}
    .note{font-size:13px;color:#444}

    footer{margin:40px auto 80px;max-width:980px;padding:0 20px;color:var(--muted)}

    /* reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 520ms cubic-bezier(.2,.9,.3,1),transform 520ms cubic-bezier(.2,.9,.3,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}

    /* Try-it modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(10,10,12,0.45);display:none;align-items:center;justify-content:center;z-index:80}
    .modal-backdrop.open{display:flex}
    .modal{width:92%;max-width:720px;background:var(--card);border-radius:14px;padding:20px;box-shadow:0 20px 60px rgba(10,10,30,0.2)}
    .modal .m-head{display:flex;justify-content:space-between;align-items:center}
    .exercise-stage{margin-top:12px}
    .breath-circle{width:140px;height:140px;border-radius:50%;margin:12px auto;background:radial-gradient(circle at 30% 30%, rgba(124,92,255,0.18), rgba(124,92,255,0.06));display:grid;place-items:center;color:var(--accent);font-weight:700}
    .breath-circle.pulse{animation:breath 4s ease-in-out infinite}
    @keyframes breath{0%{transform:scale(0.88)}50%{transform:scale(1.12)}100%{transform:scale(0.88)}}
    @media (prefers-reduced-motion:reduce){.breath-circle.pulse{animation:none}}

    .controls{display:flex;gap:8px;justify-content:center;margin-top:10px}
    .btn{padding:8px 12px;border-radius:10px;border:1px solid rgba(10,10,10,0.06);background:white;cursor:pointer}
    .btn.primary{background:var(--accent);color:white;border:0}

    /* small */
    @media (max-width:860px){.plans{grid-template-columns:1fr}.details{grid-template-columns:1fr}.logo{width:38px;height:38px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="shop.html">Shop</a>
      <a href="pricing.html" style="font-weight:800;color:var(--accent)">Plans</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <section class="hero panel reveal" data-reveal>
      <h1>Group Aromatherapy Series — Spring Cohort</h1>
      <p class="lead">A compact, cohort-based program where crafted aromatic sessions, learning circles, and mindful practices come together. Small-group pace. Safety-forward guidance. May support focus, ease, and ritual formation.</p>
      <div style="display:flex;gap:10px;align-items:center">
        <a class="enroll" href="#book">Reserve a seat</a>
        <button class="btn" id="tryNowBtn">Try it now</button>
      </div>
    </section>

    <section class="panel reveal" data-reveal>
      <h2>Why a cohort?</h2>
      <p class="muted">This format blends shared learning with personal practice. Sessions focus on scent literacy, safe dilution, and simple rituals you can fold into days. Expect guided breathing, scent journaling, and practices for intention-setting.</p>
    </section>

    <section class="plans reveal panel" data-reveal>
      <div class="plan">
        <h3>Seed Session — Intro Cohort</h3>
        <div class="price">$175 / person</div>
        <p class="muted">4 weekly sessions • 60 minutes each • 6–12 people</p>
        <ul>
          <li>Foundational scent education</li>
          <li>Two guided inhalation practices</li>
          <li>Home practice prompts + journaling template</li>
        </ul>
        <a class="enroll" href="#book">Join the seed</a>
      </div>

      <div class="plan">
        <h3>Synthesis Track — Deepen</h3>
        <div class="price">$360 / person</div>
        <p class="muted">8 weekly sessions • cohort workbook • 6–12 people</p>
        <ul>
          <li>Deeper safety and blending workshop</li>
          <li>Compound inhalation and ritual design</li>
          <li>Peer reflection circles</li>
        </ul>
        <a class="enroll" href="#book">Reserve spot</a>
      </div>

      <div class="plan">
        <h3>Keeper Access — Ongoing</h3>
        <div class="price">$55 / month</div>
        <p class="muted">Monthly small-group check-ins + library</p>
        <ul>
          <li>Monthly 60-minute group calls</li>
          <li>Access to recordings & prompts</li>
          <li>Discount on one-to-one sessions</li>
        </ul>
        <a class="enroll" href="#book">Join the circle</a>
      </div>
    </section>

    <section class="details reveal" data-reveal>
      <div class="panel faq">
        <h3>Program details & safety notes</h3>
        <h4>Session rhythm</h4>
        <p class="note">Each session includes a gentle guided practice, a short teaching segment, and time for group reflection. Practices are optional — adapt what feels safe. Sessions may include topical discussion about dilution, patch testing, and pet-safety.</p>

        <h4>Patch testing & dilution</h4>
        <p class="note">We emphasize safe dilution and recommend doing a patch test for new oils. Sample dilution guidelines and a patch-test protocol are shared in the cohort workbook. If you have specific health considerations, consult your healthcare provider.</p>

        <h4>Pregnancy & pets</h4>
        <p class="note">Some essential oils are not recommended in pregnancy or around certain animals. We provide lists of commonly cautioned oils and alternative practices. These notes are informational and do not replace professional guidance.</p>
      </div>

      <aside class="panel">
        <h4>Next cohort</h4>
        <p class="muted">Spring cohort starts the first Monday of the month. Limited seats.</p>
        <p style="margin-top:10px"><strong>Group size:</strong> 6–12 people</p>
        <p style="margin-top:10px">Want to chat about fit? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </aside>
    </section>

    <section id="book" class="panel reveal" data-reveal>
      <h3>Quick booking</h3>
      <p class="muted">Reserve a cohort seat or request a consult. No payment collected here — you receive an invoice and a short intake once you confirm.</p>
      <form id="quickBook" onsubmit="return false;" style="display:grid;gap:8px">
        <input name="name" placeholder="Your name" required style="padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06)">
        <input name="email" placeholder="Email" required style="padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06)">
        <select name="plan" style="padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06)">
          <option>Seed Session — Intro Cohort</option>
          <option>Synthesis Track — Deepen</option>
          <option>Keeper Access — Ongoing</option>
        </select>
        <div style="display:flex;gap:8px">
          <button class="btn primary" id="submitBook">Request seat</button>
          <button class="btn" id="openTry">Try a practice</button>
        </div>
      </form>
    </section>

  </main>

  <div class="modal-backdrop" id="modal">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <div class="m-head">
        <div>
          <div id="modalTitle" style="font-weight:800">Try a guided micro-practice</div>
          <div style="font-size:13px;color:var(--muted)">Choose one to explore — no sign-up required</div>
        </div>
        <button class="btn" id="closeModal">Close</button>
      </div>

      <div style="display:flex;gap:10px;margin-top:12px">
        <button class="btn" data-mode="breath">Breathing</button>
        <button class="btn" data-mode="journal">Journaling</button>
        <button class="btn" data-mode="intention">Set intention</button>
      </div>

      <div class="exercise-stage" id="exercise">
        <p class="muted">Select a practice above to begin.</p>
      </div>
    </div>
  </div>

  <footer>
    <div style="display:flex;justify-content:space-between;align-items:center">
      <div class="muted">Serving {{CITY}}, {{STATE}} • <a href="contact.html">Contact</a></div>
      <div class="muted">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script>
    // Reveal on scroll with reduced-motion support
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('[data-reveal]');
      if(prefersReduce){ items.forEach(i=>i.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting) { e.target.classList.add('visible'); obs.unobserve(e.target); }
        });
      },{threshold:0.12});
      items.forEach(i=>obs.observe(i));
    })();

    // Modal + Try-it exercises
    const modal = document.getElementById('modal');
    const exercise = document.getElementById('exercise');
    document.getElementById('tryNowBtn').addEventListener('click',()=>openModal());
    document.getElementById('openTry').addEventListener('click',()=>openModal());
    document.getElementById('closeModal').addEventListener('click',closeModal);
    modal.addEventListener('click',e=>{ if(e.target===modal) closeModal(); });

    function openModal(){ modal.classList.add('open'); renderChoice(); }
    function closeModal(){ stopBreath(); modal.classList.remove('open'); }

    function renderChoice(){ exercise.innerHTML = '<p class="muted">Select a practice above to begin.</p>'; }

    document.querySelectorAll('[data-mode]').forEach(b=>{
      b.addEventListener('click',()=>{
        const mode = b.getAttribute('data-mode');
        if(mode==='breath') startBreathing();
        if(mode==='journal') startJournaling();
        if(mode==='intention') startIntention();
      });
    });

    // Breathing micro-practice
    let breathTimer=null, breathPhase=0;
    function startBreathing(){
      stopBreath();
      exercise.innerHTML = ''+
        '<div style="text-align:center">'+
        '<div class="breath-circle pulse" id="circle">Breathe</div>'+
        '<div style="font-size:13px;color:var(--muted);margin-top:6px">Follow the circle: inhale — pause — exhale — pause</div>'+
        '<div class="controls">'+
        '<button class="btn" id="stopBreath">Stop</button>'+
        '</div>'+
        '</div>';
      const steps = ['Inhale','Hold','Exhale','Hold'];
      const durations = [4000,1200,4000,1200];
      const labelEl = document.getElementById('circle');
      breathPhase=0;
      labelEl.textContent = steps[0];
      breathTimer = setInterval(()=>{
        breathPhase = (breathPhase+1) % steps.length;
        labelEl.textContent = steps[breathPhase];
      }, 6400); // combined cycle length
      document.getElementById('stopBreath').addEventListener('click', stopBreath);
    }
    function stopBreath(){ if(breathTimer){ clearInterval(breathTimer); breathTimer=null; } }

    // Journaling micro-practice
    function startJournaling(){
      exercise.innerHTML = ''+
        '<div><label style="font-weight:700">Prompt</label><p class="muted">Name one scent-memory that brings ease. Describe it in a few lines.</p>'+
        '<textarea id="journalText" rows="6" style="width:100%;padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06)"></textarea>'+
        '<div style="display:flex;gap:8px;margin-top:8px"><button class="btn primary" id="saveJournal">Save</button><button class="btn" id="clearJournal">Clear</button></div>'+
        '<div id="journalSaved" style="margin-top:8px;color:var(--muted);font-size:13px"></div></div>';
      document.getElementById('saveJournal').addEventListener('click',()=>{
        const v = document.getElementById('journalText').value.trim();
        if(!v){ document.getElementById('journalSaved').textContent='Write a line or two to save.'; return; }
        document.getElementById('journalSaved').textContent='Saved locally in this session. Use it as a prompt for your cohort reflection.';
      });
      document.getElementById('clearJournal').addEventListener('click',()=>document.getElementById('journalText').value='');
    }

    // Intention micro-practice
    function startIntention(){
      exercise.innerHTML = ''+
        '<div><label style="font-weight:700">Set an intention</label><p class="muted">Write a short intention you can repeat later (e.g., "Return to my breath").</p>'+
        '<input id="intentInput" placeholder="I intend to..." style="width:100%;padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06)">'+
        '<div style="display:flex;gap:8px;margin-top:8px"><button class="btn primary" id="saveIntent">Save intention</button><button class="btn" id="clearIntent">Clear</button></div>'+
        '<div id="intentSaved" style="margin-top:8px;color:var(--muted);font-size:13px"></div></div>';
      document.getElementById('saveIntent').addEventListener('click',()=>{
        const v = document.getElementById('intentInput').value.trim();
        if(!v){ document.getElementById('intentSaved').textContent='Try a short phrase you can repeat.'; return; }
        document.getElementById('intentSaved').textContent='Saved for this session. Repeat it aloud or write it in your journal.';
      });
      document.getElementById('clearIntent').addEventListener('click',()=>document.getElementById('intentInput').value='');
    }

    // Quick booking feedback
    document.getElementById('submitBook').addEventListener('click',()=>{
      const form = document.getElementById('quickBook');
      const name = form.querySelector('[name=name]').value.trim();
      const email = form.querySelector('[name=email]').value.trim();
      if(!name||!email){ alert('Please add your name and email.'); return; }
      alert('Thanks, '+name+'. We will send a confirmation to '+email+' with next steps.');
      form.reset();
    });
  </script>
</body>
</html>"} 
