        <button class="btn" id="close2">Close</button>
      </div>
      <div style="margin-top:12px">
        <div id="miniCircle" style="width:120px;height:120px;border-radius:50%;margin:12px auto;background:radial-gradient(circle,#fff1f6,#fff);display:grid;place-items:center;color:var(--accent);font-weight:700">Breathe</div>
        <div style="text-align:center;color:var(--muted);font-size:13px">Follow the circle for a gentle four-count inhale and exhale.</div>
      </div>
