{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fff9;--card:#ffffff;--accent:#00a896;--muted:#5b6b6b;--radius:12px}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#0b2b2b;background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:12px 20px;background:linear-gradient(180deg,rgba(255,255,255,0.95),rgba(255,255,255,0.9));border-bottom:1px solid rgba(10,10,10,0.03);position:sticky;top:0}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .cta{background:var(--accent);color:white;padding:8px 12px;border-radius:10px;text-decoration:none}
    main{max-width:980px;margin:36px auto;padding:0 20px}
    .wrap{display:grid;grid-template-columns:1fr 380px;gap:18px}
    .panel{background:var(--card);padding:18px;border-radius:var(--radius);box-shadow:0 8px 28px rgba(5,20,10,0.04)}
    label{display:block;margin-top:8px;font-weight:700}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(10,10,10,0.06);margin-top:6px}
    .muted{color:var(--muted);font-size:13px}
    .btn{padding:10px 14px;border-radius:10px;border:0;background:var(--accent);color:white;font-weight:700}

    .reveal{opacity:0;transform:translateY(16px);transition:opacity .48s ease,transform .48s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}}

    .modal-backdrop{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(6,10,8,0.6);z-index:80}
    .modal-backdrop.open{display:flex}
    .modal{background:var(--card);padding:16px;border-radius:12px;max-width:540px;width:92%}

    @media (max-width:940px){.wrap{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#00a896,#46c2b9);display:grid;place-items:center;color:white;font-weight:800">AR</div>
      <div style="font-weight:800">Book a session</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Plans</a>
      <a class="cta" href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="panel reveal" data-reveal>
      <h2>Reserve a cohort seat or private consult</h2>
      <p class="muted">Choose below whether you’re joining a small-group series or booking a one-on-one consult. Please share any safety notes so we can prepare appropriate materials.</p>
    </section>

    <div class="wrap">
      <form id="bookingForm" class="panel reveal" data-reveal onsubmit="return false;">
        <label for="type">I’m booking:</label>
        <select id="type" name="type">
          <option value="cohort">Cohort seat (group)</option>
          <option value="private">Private consultation</option>
        </select>

        <label for="name">Name</label>
        <input id="name" name="name" required>

        <label for="email">Email</label>
        <input id="email" name="email" type="email" required>

        <label for="date">Preferred date or range</label>
        <input id="date" name="date" placeholder="e.g. Week of March 15"/>

        <label for="notes">Safety notes / allergies / pets / pregnancy</label>
        <textarea id="notes" name="notes" rows="4" placeholder="Please note anything relevant (allergies, pregnancy, or pets in the home)."></textarea>

        <div style="display:flex;gap:8px;margin-top:12px">
          <button class="btn" id="confirmBook">Request booking</button>
          <button class="btn" type="button" id="openTry3" style="background:#f1faf7;color:var(--accent);border:1px solid rgba(0,168,150,0.08)">Try a micro-practice</button>
        </div>
      </form>

      <aside class="panel reveal" data-reveal>
        <h4>What happens next?</h4>
        <p class="muted">After you request a booking you receive a short intake and an invoice. Seats are held for 48 hours pending payment. For private sessions we offer a 30-minute intake call before scheduling.</p>

        <h4 style="margin-top:12px">Safety highlights</h4>
        <ul class="muted">
          <li>We provide dilution guidance and a patch-test protocol.</li>
          <li>We list commonly cautioned oils for pregnancy and pets.</li>
          <li>Practices are optional; you may observe without participation.</li>
        </ul>
      </aside>
    </div>

    <section class="panel reveal" data-reveal style="margin-top:18px">
      <h4>Helpful resources</h4>
      <p class="muted">Before your session we recommend reviewing: a basic dilution chart, a short patch-test guide, and a list of oils commonly avoided around animals or in pregnancy. These are shared in the intake materials.</p>
    </section>
  </main>

  <div class="modal-backdrop" id="modal3">
    <div class="modal" role="dialog" aria-modal="true">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:800">Try a two-minute practice</div>
        <button class="btn" id="close3">Close</button>
      </div>
      <div id="miniPractice" style="margin-top:12px;color:var(--muted)">
        <div style="text-align:center">
          <div id="miniPulse" style="width:110px;height:110px;border-radius:50%;margin:12px auto;background:radial-gradient(circle,#e6fff9,#fff);display:grid;place-items:center;color:var(--accent);font-weight:700">Breathe</div>
          <div style="font-size:13px">A gentle four-count inhale, hold, and four-count exhale. Repeat a few times.</div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Reveal observer
    (function(){
      const prefs = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('[data-reveal]');
      if(prefs){ els.forEach(e=>e.classList.add('visible')); return; }
      const observer = new IntersectionObserver((entries)=>{ entries.forEach(entry=>{ if(entry.isIntersecting){ entry.target.classList.add('visible'); observer.unobserve(entry.target); } }); },{threshold:0.12});
      els.forEach(e=>observer.observe(e));
    })();

    // Booking logic (local simulation)
    document.getElementById('confirmBook').addEventListener('click',()=>{
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      if(!name||!email){ alert('Please enter your name and email.'); return; }
      alert('Thanks, '+name+'! We received your request and will follow up at '+email+'. Look for intake details and safety resources.');
      document.getElementById('bookingForm').reset();
    });

    // Modal micro-practice
    const modal3 = document.getElementById('modal3');
    document.getElementById('openTry3').addEventListener('click',()=>modal3.classList.add('open'));
    document.getElementById('close3').addEventListener('click',()=>modal3.classList.remove('open'));
    modal3.addEventListener('click',e=>{ if(e.target===modal3) modal3.classList.remove('open'); });
  </script>
